import ctypes
import numpy as np

def process_array(input_list):
    # Load the GSL and CBLAS libraries in the correct order
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError("Failed to load GSL libraries: " + str(e))

    # Define the function signature for the GSL function (example: gsl_sf_sin)
    gsl.gsl_sf_sin.argtypes = [ctypes.c_double, ctypes.c_int]
    gsl.gsl_sf_sin.restype = ctypes.c_double

    # Convert input list to a numpy array for efficient processing
    input_array = np.array(input_list, dtype=np.float64)

    # Process each element using the GSL function
    output_array = np.zeros_like(input_array)
    for i in range(len(input_array)):
        try:
            result = gsl.gsl_sf_sin(input_array[i], 0)
            output_array[i] = result
        except Exception as e:
            raise RuntimeError(f"Error processing element {i}: " + str(e))

    return output_array.tolist()

