        return 0

    def df(x, J, params):
        for i in range(n):
            for j in range(p):
                J[i][j] = 0.0
        return 0

    def fdf(x, f, J, params):
        for i in range(n):
            f[i] = 0.0
            for j in range(p):
                J[i][j] = 0.0
        return 0

