import numpy as np

class GaussianQuantile:
    def __init__(self):
        # Load GSL libraries in the correct order
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the function signature for gsl_cdf_gaussian_Pinv
        self.gsl.gsl_cdf_gaussian_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
        self.gsl.gsl_cdf_gaussian_Pinv.restype = ctypes.c_double

    def gaussian_quantile(self, P, sigma):
        if not (0 < P < 1):
            raise ValueError("P must be in the range (0, 1)")
        if sigma <= 0:
            raise ValueError("sigma must be greater than 0")
        return self.gsl.gsl_cdf_gaussian_Pinv(P, sigma)

