import os

def allocate_rng(rng_name):
    # Load the GSL CBLAS library first with RTLD_GLOBAL
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    except OSError:
        raise RuntimeError("Failed to load libgslcblas.so")

    # Load the GSL library
    try:
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        raise RuntimeError("Failed to load libgsl.so")

    # Define the gsl_rng_type and gsl_rng structures
    class gsl_rng_type(ctypes.Structure):
        _fields_ = []  # Fields will be determined by the library at runtime

    class gsl_rng(ctypes.Structure):
        _fields_ = []  # Fields will be determined by the library at runtime

    # Define the function signature for gsl_rng_alloc
    gsl.gsl_rng_alloc.argtypes = [ctypes.POINTER(gsl_rng_type)]
    gsl.gsl_rng_alloc.restype = ctypes.POINTER(gsl_rng)

    # Get the rng type by name
    rng_type = ctypes.POINTER(gsl_rng_type)()
    gsl.gsl_rng_env_setup()
    gsl.gsl_rng_get_typebyname.argtypes = [ctypes.c_char_p]
    gsl.gsl_rng_get_typebyname.restype = ctypes.POINTER(gsl_rng_type)

    try:
        rng_type = gsl.gsl_rng_get_typebyname(rng_name.encode('utf-8'))
    except Exception as e:
        raise ValueError(f"Invalid RNG type: {rng_name}") from e

    if not rng_type:
        raise ValueError(f"RNG type {rng_name} not found")

    # Allocate the RNG
    rng = gsl.gsl_rng_alloc(rng_type)
    if not rng:
        raise RuntimeError(f"Failed to allocate RNG of type {rng_name}")

    return rng

