            gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

            # Define the function signatures
            gsl.gsl_rstat_alloc.restype = ctypes.c_void_p
            gsl.gsl_rstat_free.argtypes = [ctypes.c_void_p]

            # Allocate workspace
            self._workspace_ptr = gsl.gsl_rstat_alloc()
            if not self._workspace_ptr:
                return False
            return True
        except Exception as e:
            return False

    def free(self):
        try:
            if self._workspace_ptr:
                gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
                gsl.gsl_rstat_free.argtypes = [ctypes.c_void_p]
                gsl.gsl_rstat_free(self._workspace_ptr)
                self._workspace_ptr = None
            return True
        except Exception as e:
            return False

