def gsl_ldexp_py(x, e):
    # Load libraries in the correct order
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the function signature for gsl_ldexp
    gsl.gsl_ldexp.argtypes = [ctypes.c_double, ctypes.c_int]
    gsl.gsl_ldexp.restype = ctypes.c_double

    # Handle edge cases
    if x == 0.0:
        return 0.0
    if e > 1023:
        return float('inf')
    if e < -1023:
        return 0.0

    # Call the GSL function
    result = gsl.gsl_ldexp(x, e)
    return float(result)

