    result = gsl.gsl_multifit_robust_name(gsl_multifit_robust_default, ctypes.byref(name_ptr), ctypes.byref(tuning_constant))
    if result == 0:
        name = name_ptr.value.decode('utf-8')
        return (name, tuning_constant.value)
    else:
        return ("Unknown", 0.0)

