import ctypes
import sys

class GslSfResult:
    def __init__(self, result):
        self.result = result

def compute_synchrotron(x):
    try:
        # Load the GSL and CBLAS libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the function signatures
        gsl_sf_synchrotron_1 = gsl.gsl_sf_synchrotron_1
        gsl_sf_synchrotron_1.argtypes = [ctypes.c_double]
        gsl_sf_synchrotron_1.restype = ctypes.c_double

        gsl_sf_synchrotron_2 = gsl.gsl_sf_synchrotron_2
        gsl_sf_synchrotron_2.argtypes = [ctypes.c_double]
        gsl_sf_synchrotron_2.restype = ctypes.c_double

        # Validate input
        if not isinstance(x, (int, float)):
            raise ValueError("Input x must be a floating-point number.")
        if x < 0:
            raise ValueError("Input x must be non-negative.")

        # Compute the synchrotron functions
        result1 = gsl_sf_synchrotron_1(ctypes.c_double(x))
        result2 = gsl_sf_synchrotron_2(ctypes.c_double(x))

        return GslSfResult((result1, result2))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return GslSfResult(None)

