gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLBlock(ctypes.Structure):
    _fields_ = [
        ("data", ctypes.POINTER(ctypes.c_double)),
        ("size1", ctypes.c_size_t),
        ("size2", ctypes.c_size_t),
        ("stride", ctypes.c_size_t),
    ]

class GSLVector(ctypes.Structure):
    _fields_ = [
        ("block", ctypes.POINTER(GSLBlock)),
        ("offset", ctypes.c_size_t),
        ("n", ctypes.c_size_t),
        ("stride", ctypes.c_size_t),
    ]

class GSLMatrix(ctypes.Structure):
    _fields_ = [
        ("block", ctypes.POINTER(GSLBlock)),
        ("size1", ctypes.c_size_t),
        ("size2", ctypes.c_size_t),
        ("tda", ctypes.c_size_t),
    ]

class GSLVectorView(ctypes.Structure):
    _fields_ = [
        ("vector", GSLVector),
    ]

# Load the function prototype for gsl_matrix_row
_gsl_matrix_row = gsl.gsl_matrix_row
_gsl_matrix_row.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.c_size_t]
_gsl_matrix_row.restype = GSLVectorView

def extract_row(matrix, row_index):
    try:
        if not isinstance(matrix, GSLMatrix):
            raise ValueError("matrix must be an instance of GSLMatrix")
        if not isinstance(row_index, int) or row_index < 0:
            raise ValueError("row_index must be a non-negative integer")

        view = _gsl_matrix_row(ctypes.byref(matrix), row_index)
        return view.vector
    except Exception as e:
        print(f"Error extracting row: {e}")
        return None

