import numpy as np

class GSLVector:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.ptr = (ctypes.c_double * self.size)(*self.data)

    def get_ptr(self):
        return ctypes.cast(self.ptr, ctypes.POINTER(ctypes.c_double))


class GSLVectorView:
    def __init__(self, vector, start, length):
        self.vector = vector
        self.start = start
        self.length = length
        self.view = ctypes.c_void_p()

        # Load the GSL libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the function signature for gsl_vector_subvector
        gsl.gsl_vector_subvector.argtypes = [
            ctypes.POINTER(ctypes.c_double),
            ctypes.c_size_t,
            ctypes.c_size_t
        ]
        gsl.gsl_vector_subvector.restype = ctypes.c_void_p

        self.view = gsl.gsl_vector_subvector(
            self.vector.get_ptr(),
            ctypes.c_size_t(self.start),
            ctypes.c_size_t(self.length)
        )

    def get_data(self):
        # Convert the view to a numpy array for easy access
        data = np.ctypeslib.as_array(
            ctypes.cast(self.view, ctypes.POINTER(ctypes.c_double)),
            shape=(self.length,)
        )
        return data.tolist()


def extract_subvector(vector, start, length):
    gsl_vector = GSLVector(vector)
    view = GSLVectorView(gsl_vector, start, length)
    return view.get_data()

