def gsl_matrix_get(matrix, i, j):
    return gsl.gsl_matrix_get(matrix, i, j)

def gsl_permutation_get(perm, i):
    return gsl.gsl_permutation_get(perm, i)

def cholesky_decomposition(input_matrix):
    n = len(input_matrix)
    matrix = gsl_matrix_alloc(n, n)
    perm = gsl_permutation_alloc(n)

    for i in range(n):
        for j in range(n):
            gsl_matrix_set(matrix, i, j, input_matrix[i][j])

    result = gsl.gsl_linalg_pcholesky_decomp(matrix, perm)

    if result != 0:
        raise RuntimeError("Cholesky decomposition failed.")

    output_matrix = [[gsl_matrix_get(matrix, i, j) for j in range(n)] for i in range(n)]
    permutation = [gsl_permutation_get(perm, i) for i in range(n)]

    gsl_matrix_free(matrix)
    gsl_permutation_free(perm)

    return (output_matrix, permutation)

