        if yrange[i] >= yrange[i + 1]:
            raise ValueError("yrange must be in increasing order.")

    c_nx = ctypes.c_size_t(nx)
    c_ny = ctypes.c_size_t(ny)
    c_xrange = (ctypes.c_double * len(xrange))(*xrange)
    c_yrange = (ctypes.c_double * len(yrange))(*yrange)

